const MAP_URL = 'https://raw.githubusercontent.com/Verkhovskiy-dev/ai-integrated-report/gh-pages/data/places_data.json?cb=' + Date.now();
const ROUTES_URL = 'https://raw.githubusercontent.com/Verkhovskiy-dev/ai-integrated-report/gh-pages/data/eken-routes.json?cb=' + Date.now();

const [map, registry] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: MAP_URL, json: true, timeout: 30000 }),
  this.helpers.httpRequest({ method: 'GET', url: ROUTES_URL, json: true, timeout: 30000 }),
]);

const enabled = new Set((registry.routes || []).filter(r => r.enabled).map(r => r.placeId));
const priority = place => {
  let score = 0;
  if (place.window?.category === 'open') score += 4;
  if (place.window?.category === 'narrowing') score += 2;
  if (place.confidence === 'high' || place.capacity?.confidence === 'high') score += 3;
  if (place.capacity?.category === 'large') score += 2;
  if (place.capacity?.category === 'medium') score += 1;
  score += Math.min(2, place.audience_lens?.length || 0);
  return score;
};

return (map.places || [])
  .filter(place => place.id && !enabled.has(place.id))
  .map(place => ({ place, priority: priority(place) }))
  .sort((a, b) => b.priority - a.priority || a.place.id.localeCompare(b.place.id))
  .slice(0, 3)
  .map(job => ({ json: {
    mode: 'shadow',
    mapVersion: map.meta?.version || null,
    placeId: job.place.id,
    priority: job.priority,
    place: job.place,
    agent_input: JSON.stringify(job.place),
  }}));

const outputs = $input.all();
const jobs = $('Plan Route Jobs').all();

return outputs.map((item, index) => {
  const raw = String(item.json.output || item.json.text || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  let draft = null;
  let parseError = null;
  try { draft = JSON.parse(raw); } catch (error) { parseError = String(error.message); }
  return { json: {
    mode: 'shadow',
    placeId: jobs[index]?.json?.placeId || null,
    mapVersion: jobs[index]?.json?.mapVersion || null,
    priority: jobs[index]?.json?.priority || null,
    place: jobs[index]?.json?.place || null,
    draft,
    parseError,
  }};
});

const outputs = $input.all();
const drafts = $('Normalize Draft').all();

return outputs.map((item, index) => {
  const raw = String(item.json.output || item.json.text || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  let qa = null;
  let qaParseError = null;
  try { qa = JSON.parse(raw); } catch (error) { qaParseError = String(error.message); }
  const source = drafts[index]?.json || {};
  return { json: {
    mode: 'shadow',
    publishAllowed: false,
    placeId: source.placeId || qa?.placeId || null,
    mapVersion: source.mapVersion || null,
    priority: source.priority || null,
    draft: source.draft || null,
    builderParseError: source.parseError || null,
    qa,
    qaParseError,
    nextState: qa?.approved ? 'manual-review' : 'needs-revision',
  }};
});
